import { expect } from "chai";
import { ethers } from "hardhat";
import { EternaWill } from "../typechain-types";
import { SignerWithAddress } from "@nomicfoundation/hardhat-ethers/signers";

describe("EternaWill", function () {
  let eternaWill: EternaWill;
  let owner: SignerWithAddress;
  let beneficiary1: SignerWithAddress;
  let beneficiary2: SignerWithAddress;
  let guardian1: SignerWithAddress;
  let guardian2: SignerWithAddress;
  let guardian3: SignerWithAddress;
  let executor: SignerWithAddress;

  const ENCRYPTED_HASH = ethers.keccak256(ethers.toUtf8Bytes("test-will-data"));
  const INACTIVITY_PERIOD = 14 * 24 * 60 * 60; // 14 days (in seconds, for testing)

  beforeEach(async function () {
    [owner, beneficiary1, beneficiary2, guardian1, guardian2, guardian3, executor] =
      await ethers.getSigners();

    const EternaWill = await ethers.getContractFactory("EternaWill");
    eternaWill = await EternaWill.deploy();
    await eternaWill.waitForDeployment();
  });

  describe("Will Creation", function () {
    it("should create a will with valid parameters", async function () {
      const beneficiaries = [beneficiary1.address, beneficiary2.address];
      const percentages = [6000, 4000]; // 60% + 40% = 100%
      const names = ["Alice", "Bob"];
      const delays = [0, 0];
      const guardians = [guardian1.address, guardian2.address, guardian3.address];
      const guardianNames = ["Guardian1", "Guardian2", "Guardian3"];
      const triggerConfig = {
        inactivityPeriod: INACTIVITY_PERIOD,
        guardianThreshold: 2,
        minGuardians: 2,
        useOracle: false,
      };

      await expect(
        eternaWill.connect(owner).createWill(
          beneficiaries, percentages, names, delays,
          guardians, guardianNames, triggerConfig, ENCRYPTED_HASH
        )
      ).to.emit(eternaWill, "WillCreated");

      const will = await eternaWill.getWill(0);
      expect(will.owner).to.equal(owner.address);
      expect(will.status).to.equal(0); // Active
      expect(will.encryptedDataHash).to.equal(ENCRYPTED_HASH);
      expect(will.triggerConfig.inactivityPeriod).to.equal(INACTIVITY_PERIOD);
      expect(will.triggerConfig.guardianThreshold).to.equal(2);
    });

    it("should reject invalid percentage totals", async function () {
      const beneficiaries = [beneficiary1.address, beneficiary2.address];
      const percentages = [5000, 3000]; // Only 80%, not 100%
      const names = ["Alice", "Bob"];
      const delays = [0, 0];
      const guardians = [guardian1.address, guardian2.address];
      const guardianNames = ["Guardian1", "Guardian2"];
      const triggerConfig = {
        inactivityPeriod: INACTIVITY_PERIOD,
        guardianThreshold: 2,
        minGuardians: 2,
        useOracle: false,
      };

      await expect(
        eternaWill.connect(owner).createWill(
          beneficiaries, percentages, names, delays,
          guardians, guardianNames, triggerConfig, ENCRYPTED_HASH
        )
      ).to.be.revertedWithCustomError(eternaWill, "InvalidPercentages");
    });

    it("should reject empty beneficiaries", async function () {
      await expect(
        eternaWill.connect(owner).createWill(
          [], [], [], [],
          [guardian1.address], ["Guardian1"],
          { inactivityPeriod: INACTIVITY_PERIOD, guardianThreshold: 1, minGuardians: 1, useOracle: false },
          ENCRYPTED_HASH
        )
      ).to.be.revertedWithCustomError(eternaWill, "InvalidBeneficiaries");
    });

    it("should reject with too few guardians", async function () {
      await expect(
        eternaWill.connect(owner).createWill(
          [beneficiary1.address], [10000], ["Alice"], [0],
          [guardian1.address], ["Guardian1"],
          { inactivityPeriod: INACTIVITY_PERIOD, guardianThreshold: 2, minGuardians: 2, useOracle: false },
          ENCRYPTED_HASH
        )
      ).to.be.revertedWithCustomError(eternaWill, "NotEnoughGuardians");
    });
  });

  describe("Heartbeat", function () {
    beforeEach(async function () {
      await eternaWill.connect(owner).createWill(
        [beneficiary1.address], [10000], ["Alice"], [0],
        [guardian1.address, guardian2.address], ["G1", "G2"],
        { inactivityPeriod: INACTIVITY_PERIOD, guardianThreshold: 2, minGuardians: 2, useOracle: false },
        ENCRYPTED_HASH
      );
    });

    it("should register heartbeat", async function () {
      await expect(eternaWill.connect(owner).checkIn(0))
        .to.emit(eternaWill, "Heartbeat");

      const will = await eternaWill.getWill(0);
      expect(will.lastHeartbeat).to.be.closeTo(
        Math.floor(Date.now() / 1000),
        60
      );
    });

    it("should reject heartbeat from non-owner", async function () {
      await expect(
        eternaWill.connect(beneficiary1).checkIn(0)
      ).to.be.revertedWithCustomError(eternaWill, "NotOwner");
    });

    it("should reject heartbeat too soon", async function () {
      await eternaWill.connect(owner).checkIn(0);
      await expect(
        eternaWill.connect(owner).checkIn(0)
      ).to.be.revertedWithCustomError(eternaWill, "HeartbeatTooSoon");
    });
  });

  describe("Guardian Voting", function () {
    beforeEach(async function () {
      await eternaWill.connect(owner).createWill(
        [beneficiary1.address], [10000], ["Alice"], [0],
        [guardian1.address, guardian2.address, guardian3.address], ["G1", "G2", "G3"],
        { inactivityPeriod: INACTIVITY_PERIOD, guardianThreshold: 2, minGuardians: 2, useOracle: false },
        ENCRYPTED_HASH
      );
    });

    it("should allow guardian to vote", async function () {
      await expect(eternaWill.connect(guardian1).guardianVote(0, true))
        .to.emit(eternaWill, "GuardianVoted");

      const (votesFor, total) = await eternaWill.getGuardianVoteStatus(0);
      expect(votesFor).to.equal(1);
      expect(total).to.equal(3);
    });

    it("should prevent double voting", async function () {
      await eternaWill.connect(guardian1).guardianVote(0, true);
      await expect(
        eternaWill.connect(guardian1).guardianVote(0, true)
      ).to.be.revertedWithCustomError(eternaWill, "AlreadyVoted");
    });

    it("should reject vote from non-guardian", async function () {
      await expect(
        eternaWill.connect(beneficiary1).guardianVote(0, true)
      ).to.be.revertedWithCustomError(eternaWill, "NotGuardian");
    });
  });

  describe("Execution", function () {
    beforeEach(async function () {
      await eternaWill.connect(owner).createWill(
        [beneficiary1.address, beneficiary2.address], [6000, 4000], ["Alice", "Bob"], [0, 0],
        [guardian1.address, guardian2.address, guardian3.address], ["G1", "G2", "G3"],
        { inactivityPeriod: 1, guardianThreshold: 2, minGuardians: 2, useOracle: false },
        ENCRYPTED_HASH
      );

      // Advance time past inactivity period (1 second)
      await ethers.provider.send("evm_increaseTime", [2]);
      await ethers.provider.send("evm_mine", []);

      // Guardians vote deceased
      await eternaWill.connect(guardian1).guardianVote(0, true);
      await eternaWill.connect(guardian2).guardianVote(0, true);
    });

    it("should check executability", async function () {
      const (canExecute, confidence) = await eternaWill.checkExecutable(0);
      expect(canExecute).to.be.true;
      expect(confidence).to.be.gte(7000);
    });

    it("should execute will after triggers met", async function () {
      await expect(eternaWill.connect(executor).executeWill(0))
        .to.emit(eternaWill, "WillExecuted");

      const will = await eternaWill.getWill(0);
      expect(will.status).to.equal(1); // Executed
    });

    it("should distribute ETH after execution", async function () {
      // Fund contract with ETH
      await owner.sendTransaction({
        to: await eternaWill.getAddress(),
        value: ethers.parseEther("10.0"),
      });

      await eternaWill.connect(executor).executeWill(0);

      await expect(eternaWill.connect(executor).distributeETH(0))
        .to.emit(eternaWill, "AssetsClaimed");

      const bal1 = await ethers.provider.getBalance(beneficiary1.address);
      expect(bal1).to.be.closeTo(
        ethers.parseEther("6.0"),
        ethers.parseEther("0.01") // Gas
      );
    });

    it("should prevent double execution", async function () {
      await eternaWill.connect(executor).executeWill(0);
      await expect(
        eternaWill.connect(executor).executeWill(0)
      ).to.be.reverted;
    });
  });

  describe("Will Management", function () {
    beforeEach(async function () {
      await eternaWill.connect(owner).createWill(
        [beneficiary1.address], [10000], ["Alice"], [0],
        [guardian1.address, guardian2.address], ["G1", "G2"],
        { inactivityPeriod: INACTIVITY_PERIOD, guardianThreshold: 2, minGuardians: 2, useOracle: false },
        ENCRYPTED_HASH
      );
    });

    it("should allow owner to revoke will", async function () {
      await expect(eternaWill.connect(owner).revokeWill(0))
        .to.emit(eternaWill, "WillRevoked");

      const will = await eternaWill.getWill(0);
      expect(will.status).to.equal(2); // Revoked
    });

    it("should reject execution of revoked will", async function () {
      await eternaWill.connect(owner).revokeWill(0);
      const (canExecute,) = await eternaWill.checkExecutable(0);
      expect(canExecute).to.be.false;
    });

    it("should allow guardian management", async function () {
      await eternaWill.connect(owner).addGuardian(0, guardian3.address, "G3");
      expect(await eternaWill.isGuardian(0, guardian3.address)).to.be.true;

      await eternaWill.connect(owner).removeGuardian(0, guardian1.address);
      expect(await eternaWill.isGuardian(0, guardian1.address)).to.be.false;
    });
  });
});

