 * POST /api/wills/:id/heartbeat — Send heartbeat
 * Body: { "privateKey": "0x..." }
 */
router.post("/wills/:id/heartbeat", async (req: Request, res: Response) => {
  try {
    const willId = parseInt(req.params.id, 10);
    if (isNaN(willId)) {
      return res.status(400).json({ error: "Invalid will ID" });
    }

    const { privateKey } = req.body;
    if (!privateKey) {
      return res.status(400).json({ error: "privateKey is required" });
    }

    const success = await sendHeartbeat(willId, privateKey);
    if (success) {
      res.json({ ok: true, message: "Heartbeat registered" });
    } else {
      res.status(400).json({ error: "Failed to send heartbeat" });
    }
  } catch (err) {
    console.error("[API] Heartbeat error:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

/**
 * GET /api/wills/owner/:address — Get wills for an owner
 */
router.get("/wills/owner/:address", async (req: Request, res: Response) => {
  try {
    const contract = getContract();
    const willIds = await contract.getOwnerWills(req.params.address);
    res.json({ owner: req.params.address, willIds: willIds.map(Number) });
  } catch (err) {
    console.error("[API] Error fetching owner wills:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

/**
 * GET /api/wills/:id/claim — Get claim info for beneficiary
 */
router.get("/wills/:id/claim", async (req: Request, res: Response) => {
  try {
    const willId = parseInt(req.params.id, 10);
    if (isNaN(willId)) {
      return res.status(400).json({ error: "Invalid will ID" });
    }

    const contract = getContract();
    const will = await contract.getWill(willId);
    const status = Number(will.status);

    if (status !== 1) {
      return res.json({
        willId,
        status: ["Active", "Executed", "Revoked"][status],
        claimable: false,
        message: "Will has not been executed yet.",
      });
    }

    const beneficiaries = await getBeneficiaryDetails(willId);
    const executedAt = Number(will.executedAt);
    const now = Math.floor(Date.now() / 1000);
    const claimDeadline = executedAt + 365 * 24 * 60 * 60; // 1 year

    res.json({
      willId,
      status: "Executed",
      executedAt: new Date(executedAt * 1000).toISOString(),
      claimable: now < claimDeadline,
      claimDeadline: new Date(claimDeadline * 1000).toISOString(),
      beneficiaries,
    });
  } catch (err) {
    console.error("[API] Error fetching claim info:", err);
    res.status(500).json({ error: "Internal server error" });
  }
});

export default router;

import express from "express";
import cors from "cors";
import cron from "node-cron";
import { config } from "./config.js";
import { initContract } from "./contract.js";
import { agentTick } from "./agent.js";
import apiRouter from "./api.js";

const app = express();

// Middleware
app.use(cors());
app.use(express.json());

// API routes
app.use("/api", apiRouter);

// Health check
app.get("/", (_req, res) => {
  res.json({
    name: "Eterna Backend",
    version: "1.0.0",
    status: "running",
    agentPollIntervalMs: config.agent.pollIntervalMs,
  });
});

// Start server
async function start() {
  try {
    // Initialize contract connection
    if (config.contractAddress && config.privateKey) {
      initContract();
      console.log("[Startup] Contract initialized");

      // Start AI Agent cron job
      const cronExpression = `*/${Math.max(1, Math.floor(config.agent.pollIntervalMs / 60000))} * * * *`;
      cron.schedule(cronExpression, () => {
        agentTick().catch((err) => console.error("[Cron] Agent tick error:", err));
      });
      console.log(`[Startup] AI Agent cron scheduled: "${cronExpression}"`);

      // Run initial scan
      agentTick().catch((err) => console.error("[Startup] Initial scan error:", err));
    } else {
      console.warn("[Startup] CONTRACT_ADDRESS or PRIVATE_KEY not set — running in API-only mode");
      console.warn("[Startup] Set these env vars to enable AI Agent functionality");
    }

    app.listen(config.port, () => {
      console.log(`[Startup] Eterna Backend running on http://localhost:${config.port}`);
      console.log(`[Startup] API docs: http://localhost:${config.port}/api/status`);
    });
  } catch (err) {
    console.error("[Startup] Fatal error:", err);
    process.exit(1);
  }
}

start();

