"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useAccount } from "wagmi";
import { ConnectButton } from "@rainbow-me/rainbowkit";
import { isGuardian, getWill, getGuardians, voteAsGuardian, WILL_STATUS } from "@/lib/eterna";

export default function GuardianPage() {
  const { id } = useParams<{ id: string }>();
  const { address, isConnected } = useAccount();
  const router = useRouter();
  const willId = BigInt(id);

  const [will, setWill] = useState<any>(null);
  const [guardians, setGuardians] = useState<any[]>([]);
  const [myVote, setMyVote] = useState<any>(null);
  const [isValidGuardian, setIsValidGuardian] = useState(false);
  const [loading, setLoading] = useState(true);
  const [voting, setVoting] = useState(false);
  const [voted, setVoted] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!address || !isConnected) return;
    loadData();
  }, [id, address, isConnected]);

  async function loadData() {
    setLoading(true);
    try {
      const [w, g] = await Promise.all([
        getWill(willId),
        getGuardians(willId),
      ]);
      setWill(w);
      setGuardians(g);

      const isG = await isGuardian(willId, address!);
      setIsValidGuardian(isG);

      if (isG) {
        const myG = g.find(
          (guard: any) => guard.wallet.toLowerCase() === address!.toLowerCase()
        );
        setMyVote(myG);
        if (myG?.hasVoted) setVoted(true);
      }
    } catch (err) {
      console.error("Error loading guardian data:", err);
    } finally {
      setLoading(false);
    }
  }

  const handleVote = async (deceased: boolean) => {
    setVoting(true);
    setError("");
    try {
      await voteAsGuardian(willId, deceased);
      setVoted(true);
      loadData();
    } catch (err: any) {
      setError(err?.shortMessage || "Transaction failed");
    } finally {
      setVoting(false);
    }
  };

  if (!isConnected) {
    return (
      <div className="flex-1 flex items-center justify-center px-4">
        <div className="text-center card max-w-md">
          <div className="text-4xl mb-4">🛡️</div>
          <h2 className="text-xl font-bold mb-4">Guardian Verification</h2>
          <p className="text-gray-400 mb-6">
            Connect your wallet to verify your identity as a guardian.
          </p>
          <ConnectButton />
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-purple-500/30 border-t-purple-500 rounded-full animate-spin" />
      </div>
    );
  }

  if (!will || !isValidGuardian) {
    return (
      <div className="flex-1 flex items-center justify-center px-4">
        <div className="card text-center max-w-md">
          <div className="text-4xl mb-4">🚫</div>
          <h2 className="text-xl font-bold mb-2">Access Denied</h2>
          <p className="text-gray-400">
            You are not registered as a guardian for Will #{id}, or this will does not exist.
          </p>
        </div>
      </div>
    );
  }

  const willStatus = Number(will.status);
  const totalGuardians = guardians.length;
  const votesFor = guardians.filter((g) => g.hasVoted && g.vote).length;
  const guardiansVoted = guardians.filter((g) => g.hasVoted).length;

  return (
    <div className="flex-1 flex items-center justify-center px-4 py-8">
      <div className="max-w-lg w-full animate-fade-in">
        <div className="card card-glow">
          <div className="text-center mb-6">
            <div className="text-4xl mb-3">🛡️</div>
            <h1 className="text-2xl font-bold">Guardian Dashboard</h1>
            <p className="text-gray-400 text-sm mt-1">Will #{id}</p>
          </div>

          <div className="flex items-center justify-center gap-6 mb-6 text-sm">
            <div className="text-center">
              <p className="text-2xl font-bold text-white">{votesFor}/{totalGuardians}</p>
              <p className="text-gray-500">Votes For</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-white">{guardiansVoted}/{totalGuardians}</p>
              <p className="text-gray-500">Voted</p>
            </div>
            <div className="text-center">
              <span
                className={`px-2 py-1 rounded-full text-xs ${
                  willStatus === 0 ? "bg-emerald-900/30 text-emerald-400" : "bg-gray-800 text-gray-400"
                }`}
              >
                {WILL_STATUS[willStatus]}
              </span>
            </div>
          </div>

          {voted ? (
            <div className="text-center py-6">
              <div className="text-5xl mb-3">✅</div>
              <h3 className="text-lg font-semibold mb-1">Vote Recorded</h3>
              <p className="text-gray-400 text-sm">
                Your vote has been submitted on-chain. Thank you for fulfilling your duty as a guardian.
              </p>
              <button
                onClick={() => router.push(`/will/${id}`)}
                className="btn-primary mt-6"
              >
                View Will Details
              </button>
            </div>
          ) : (
            <>
              <div className="mb-6">
                <h3 className="font-semibold text-center mb-2">
                  Has the owner of this will passed away?
                </h3>
                <p className="text-gray-400 text-sm text-center">
                  Your identity has been verified. Please vote based on your knowledge.
                </p>
              </div>

              {error && (
                <div className="mb-4 p-3 bg-red-900/30 border border-red-500/30 rounded-lg text-sm text-red-300">
                  {error}
                </div>
              )}

              <div className="flex gap-3">
                <button
                  onClick={() => handleVote(true)}
                  disabled={voting}
                  className="btn-primary flex-1 py-4"
                >
                  {voting ? "Confirming..." : "☑️ Yes, Deceased"}
                </button>
                <button
                  onClick={() => handleVote(false)}
                  disabled={voting}
                  className="btn-secondary flex-1 py-4"
                >
                  ❌ No, Still Alive
                </button>
              </div>
            </>
          )}

          {/* Guardian list */}
          <div className="mt-6 pt-6 border-t border-white/5">
            <h4 className="text-sm font-medium text-gray-400 mb-3">All Guardians</h4>
            {guardians.map((g: any, i: number) => (
              <div key={i} className="flex items-center justify-between py-2 text-sm">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full bg-gray-600" />
                  <span>{g.name}</span>
                </div>
                <span className={g.hasVoted ? "text-emerald-400" : "text-gray-500"}>
                  {g.hasVoted ? (g.vote ? "Voted: Deceased" : "Voted: Alive") : "Not voted"}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { useAccount } from "wagmi";
import { ConnectButton } from "@rainbow-me/rainbowkit";
import { getWill, getBeneficiaries, getWillStatus, WILL_STATUS } from "@/lib/eterna";
import { formatEther } from "viem";

export default function ClaimPage() {
  const { id } = useParams<{ id: string }>();
  const { address, isConnected } = useAccount();
  const willId = BigInt(id);

  const [will, setWill] = useState<any>(null);
  const [beneficiaries, setBeneficiaries] = useState<any[]>([]);
  const [isBeneficiary, setIsBeneficiary] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, [id]);

  async function loadData() {
    setLoading(true);
    try {
      const [w, b] = await Promise.all([
        getWill(willId),
        getBeneficiaries(willId),
      ]);
      setWill(w);
      setBeneficiaries(b);

      if (address) {
        const isBen = b.some(
          (ben: any) => ben.wallet.toLowerCase() === address.toLowerCase()
        );
        setIsBeneficiary(isBen);
      }
    } catch (err) {
      console.error("Error loading claim data:", err);
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-purple-500/30 border-t-purple-500 rounded-full animate-spin" />
      </div>
    );
  }

  const willStatus = will ? Number(will.status) : 0;
  const isExecuted = willStatus === 1;

  return (
    <div className="flex-1 flex items-center justify-center px-4 py-8">
      <div className="max-w-lg w-full animate-fade-in">
        {/* Beneficiary match */}
        {isConnected && isBeneficiary && isExecuted && (
          <BeneficiaryClaimPanel willId={willId} beneficiaries={beneficiaries} address={address!} />
        )}

        {/* Will info */}
        <div className="card mt-6">
          <div className="flex items-center gap-3 mb-4">
            <div className="text-2xl">📜</div>
            <div>
              <h2 className="text-xl font-bold">Will #{id}</h2>
              <span
                className={`text-sm ${
                  isExecuted ? "text-emerald-400" : willStatus === 0 ? "text-yellow-400" : "text-gray-500"
                }`}
              >
                {WILL_STATUS[willStatus]}
              </span>
            </div>
          </div>

          <div className="space-y-3">
            <h3 className="font-semibold">Beneficiaries</h3>
            {beneficiaries.map((b: any, i: number) => (
              <div key={i} className="flex items-center justify-between py-2 border-b border-white/5 last:border-0">
                <div>
                  <p className="font-medium">{b.name}</p>
                  <p className="text-xs text-gray-500 font-mono">{b.wallet}</p>
                </div>
                <div className="text-right">
                  <p className="font-bold gradient-text">{Number(b.percentage) / 100}%</p>
                  {b.claimed && <p className="text-xs text-emerald-400">Claimed ✅</p>}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Connect wallet prompt */}
        {!isConnected && (
          <div className="card text-center mt-6">
            <p className="text-gray-400 mb-4">Connect your wallet to check if you are a beneficiary</p>
            <ConnectButton />
          </div>
        )}
      </div>
    </div>
  );
}

function BeneficiaryClaimPanel({
  willId,
  beneficiaries,
  address,
}: {
  willId: bigint;
  beneficiaries: any[];
  address: `0x${string}`;
}) {
  const [claiming, setClaiming] = useState(false);
  const [claimed, setClaimed] = useState(false);
  const [error, setError] = useState("");

  const myBeneficiary = beneficiaries.find(
    (b: any) => b.wallet.toLowerCase() === address.toLowerCase()
  );

  if (myBeneficiary?.claimed || claimed) {
    return (
      <div className="card card-glow border-emerald-500/20 text-center">
        <div className="text-5xl mb-4">✅</div>
        <h2 className="text-2xl font-bold mb-2">Claimed!</h2>
        <p className="text-gray-400">
          Your inheritance has been successfully claimed.
        </p>
      </div>
    );
  }

  const handleClaim = async () => {
    setClaiming(true);
    setError("");
    try {
      // In a full implementation, this would call the distribution contract
      // For now we show the claim was submitted
      await new Promise((r) => setTimeout(r, 2000));

      // Simulating successful claim
      setClaimed(true);
    } catch (err: any) {
      setError(err?.message || "Claim failed");
    } finally {
      setClaiming(false);
    }
  };

  return (
    <div className="card card-glow">
      <div className="text-center mb-6">
        <div className="text-5xl mb-4">🎉</div>
        <h2 className="text-2xl font-bold mb-2">You Are a Beneficiary!</h2>
        <p className="text-gray-400">
          The owner of Will #{Number(willId)} has designated you as a beneficiary.
          Your share is ready to claim.
        </p>
      </div>

      <div className="mb-6 p-4 bg-emerald-900/20 rounded-lg border border-emerald-500/20 text-center">
        <p className="text-sm text-gray-400">Your Allocation</p>
        <p className="text-3xl font-bold gradient-text">
          {Number(myBeneficiary?.percentage) / 100}%
        </p>
        <p className="text-xs text-gray-500 mt-1">of the estate</p>
