/**
 * Eterna Demo Seed Script
 *
 * Used for hackathon demo to set up a pre-configured scenario:
 * 1. Deploy EternaWill contract
 * 2. Create a will with beneficiaries and guardians
 * 3. Advance time past inactivity period
 * 4. Simulate guardian votes
 * 5. Show execution status
 *
 * Usage: npx hardhat run scripts/seed.ts --network hardhat
 */

import { ethers } from "hardhat";

async function main() {
  console.log("🚀 Eterna Demo Seed Script");
  console.log("==========================\n");

  // Get signers
  const [owner, alice, bob, guard1, guard2, guard3] = await ethers.getSigners();

  // Deploy contract
  console.log("1. Deploying EternaWill...");
  const EternaWill = await ethers.getContractFactory("EternaWill");
  const contract = await EternaWill.deploy();
  await contract.waitForDeployment();
  const contractAddress = await contract.getAddress();
  console.log(`   ✅ Deployed at: ${contractAddress}\n`);

  // Create will
  console.log("2. Creating Will...");
  const beneficiaries = [alice.address, bob.address];
  const percentages = [6000, 4000]; // 60% Alice, 40% Bob
  const names = ["Alice (Mom)", "Bob (Brother)"];
  const delays = [0, 0]; // Immediate for both
  const guardians = [guard1.address, guard2.address, guard3.address];
  const guardianNames = ["Guardian 1 - Dr. Lee", "Guardian 2 - Lawyer Kim", "Guardian 3 - Sarah"];

  const ENCRYPTED_HASH = ethers.keccak256(ethers.toUtf8Bytes("eterna-demo-will-001"));

  const tx = await contract.createWill(
    beneficiaries, percentages, names, delays,
    guardians, guardianNames,
    {
      inactivityPeriod: 1, // 1 second (for demo)
      guardianThreshold: 2,
      minGuardians: 2,
      useOracle: false,
    },
    ENCRYPTED_HASH
  );
  const receipt = await tx.wait();
  const willId = 0;
  console.log(`   ✅ Will #${willId} created\n`);

  // Show will status
  let willData = await contract.getWill(willId);
  console.log(`3. Will Status: Active (0 = Active, 1 = Executed, 2 = Revoked)`);
  console.log(`   Status: ${willData.status}`);
  console.log(`   Owner: ${willData.owner}`);
  console.log(`   Inactivity Period: ${willData.triggerConfig.inactivityPeriod}s\n`);

  // Advance time past inactivity period
  console.log("4. Simulating inactivity...");
  await ethers.provider.send("evm_increaseTime", [2]);
  await ethers.provider.send("evm_mine", []);
  console.log(`   ✅ Time advanced by 2 seconds\n`);

  // Guardians vote
  console.log("5. Guardians voting...");
  await contract.connect(guard1).guardianVote(willId, true);
  console.log(`   ✅ Guardian 1 voted: Deceased`);
  await contract.connect(guard2).guardianVote(willId, true);
  console.log(`   ✅ Guardian 2 voted: Deceased`);
  console.log(`   ⏳ Guardian 3 has not voted yet\n`);

  // Check executability
  const [canExecute, confidence] = await contract.checkExecutable(willId);
  console.log(`6. Execution Check:`);
  console.log(`   Can Execute: ${canExecute}`);
  console.log(`   Confidence: ${Number(confidence) / 100}%\n`);

  // Execute will
  console.log("7. Executing Will...");
  if (canExecute) {
    const execTx = await contract.executeWill(willId);
    await execTx.wait();
    console.log(`   ✅ Will #${willId} Executed!\n`);
  } else {
    console.log(`   ❌ Cannot execute yet\n`);
  }

  // Fund contract with ETH
  console.log("8. Funding contract with test ETH...");
  const fundAmount = ethers.parseEther("10.0");
  await owner.sendTransaction({
    to: contractAddress,
    value: fundAmount,
  });
  console.log(`   ✅ Contract funded with ${ethers.formatEther(fundAmount)} ETH\n`);

  // Distribute
  console.log("9. Distributing assets...");
  const distTx = await contract.distributeETH(willId);
  await distTx.wait();
  console.log(`   ✅ Assets distributed!\n`);

  // Show final balances
  console.log("10. Final Balances:");
  console.log(`   Alice (60%): ${ethers.formatEther(await ethers.provider.getBalance(alice.address))} ETH`);
  console.log(`   Bob (40%):   ${ethers.formatEther(await ethers.provider.getBalance(bob.address))} ETH\n`);

  console.log("==========================");
  console.log("✅ Demo Ready!");
  console.log(`Contract: ${contractAddress}`);
  console.log(`Owner:    ${owner.address}`);
  console.log(`Alice:    ${alice.address}`);
  console.log(`Bob:      ${bob.address}`);
  console.log(`Guardian1: ${guard1.address}`);
  console.log(`Guardian2: ${guard2.address}`);
  console.log(`Guardian3: ${guard3.address}`);
  console.log("==========================");
}

main().catch(console.error);

